import sys
from datetime import datetime, timezone


def fmt(dt):
    """Format an aware datetime as YYYY-MM-DDTHH:MM:SSZ in UTC."""
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = datetime.fromisoformat(data["as_of"])

    items = []
    for r in data.get("reminders", []):
        if r.get("completed"):
            continue
        due = r.get("due")
        if due is None:
            continue
        try:
            dt = datetime.fromisoformat(str(due))
        except (ValueError, TypeError):
            continue
        # Skip naive datetimes (no explicit offset).
        if dt.tzinfo is None:
            continue
        # Include due AT OR BEFORE as_of, comparing actual instants.
        if dt <= as_of:
            items.append((dt, r["id"], r["title"]))

    # Sort by actual due instant, then by id.
    items.sort(key=lambda t: (t[0], str(t[1])))

    result = [
        {"id": i, "title": t, "due_utc": fmt(dt)} for (dt, i, t) in items
    ]

    print(json.dumps(result, ensure_ascii=False))


main()"}

